// ---- Shared helpers (same block in every FS Code node) ----
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const truthy = (v) => v === true || ['TRUE', 'YES', 'Y', '1'].includes(str(v).toUpperCase());
const FIELD_TYPES = ['text', 'longtext', 'email', 'phone', 'number', 'date', 'dropdown', 'checkbox'];

function normalizeEvents(rows) {
  return rows
    .filter((r) => str(r.event_id))
    .map((r) => ({
      event_id: str(r.event_id),
      event_name: str(r.event_name) || str(r.event_id),
      target_tab: str(r.target_tab) || ('Data_' + str(r.event_id)),
      is_default: truthy(r.is_default),
      // a blank "active" cell counts as active
      active: str(r.active) === '' ? true : truthy(r.active),
    }));
}

function normalizeFields(rows, eventId) {
  const seen = new Set();
  return rows
    .filter((r) => str(r.event_id) === eventId && str(r.field_key))
    .map((r, i) => {
      const type = str(r.field_type).toLowerCase();
      const order = Number(str(r.order));
      return {
        key: str(r.field_key),
        label: str(r.form_label) || str(r.field_key),
        type: FIELD_TYPES.includes(type) ? type : 'text',
        required: truthy(r.required),
        options: str(r.options).split(/[,|]/).map((o) => o.trim()).filter(Boolean),
        hint: str(r.ai_hint),
        order: Number.isFinite(order) && str(r.order) !== '' ? order : 1000 + i,
      };
    })
    .sort((a, b) => a.order - b.order)
    .filter((f) => (seen.has(f.key) ? false : seen.add(f.key)));
}

// Normalizes a single value to the format that gets stored in the sheet.
function cleanValue(field, value) {
  let v = str(value);
  switch (field.type) {
    case 'email':
      return v.replace(/\s+/g, '').toLowerCase();
    case 'phone':
      return v.replace(/[^\d+]/g, '');
    case 'checkbox':
      return v === '' ? '' : (truthy(v) || ['CHECKED', 'X', '✓', '✔'].includes(v.toUpperCase()) ? 'TRUE' : 'FALSE');
    case 'dropdown': {
      const match = field.options.find((o) => o.toLowerCase() === v.toLowerCase());
      return match || v;
    }
    default:
      return v;
  }
}
// ---- End shared helpers ----

// Builds the event list (with field mappings) for the web app.
const eventRows = $('Read Events').all().map((i) => i.json);
const fieldRows = $('Read Fields').all().map((i) => i.json);

const warnings = [];
const events = [];
for (const e of normalizeEvents(eventRows)) {
  if (!e.active) continue;
  const fields = normalizeFields(fieldRows, e.event_id);
  if (!fields.length) {
    warnings.push(`Event ${e.event_id} has no rows in the Fields tab, so it is hidden.`);
    continue;
  }
  events.push({
    event_id: e.event_id,
    event_name: e.event_name,
    is_default: e.is_default,
    fields: fields.map(({ order, ...f }) => f),
  });
}

const def = events.find((e) => e.is_default);
return [{
  json: {
    ok: true,
    events,
    default_event_id: def ? def.event_id : null,
    warnings,
  },
}];
